// 大名能力値取得ヘルパー
function getClanAbility(clanId) {
  const abilities = window.CLAN_ABILITIES || {};











  return abilities[clanId] || abilities['default'] || { politics: 60, military: 60, stratagem: 55, personality: 'balanced' };
}

