      statsEl.textContent = `${this.year}年 ${this.seasonNames[this.seasonIdx]} 達成 ｜ 支配領国: ${myProvs.length}州 ｜ 激闘戦歴: ${this.stats.battlesWon}勝 (${this.stats.battlesFought}戦)`;
